using System;
using System.Collections.Generic;
using System.Linq;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace Underwater.Editor {
public static class ReefRenderAudit {
 public static void Capture(){Run();System.IO.Directory.CreateDirectory("Renders/FishDetailFix");var camera=Camera.main;camera.transform.rotation=Quaternion.identity;UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>().Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/FishDetailFix/DistanceMeshes.png");foreach(var detail in UnityEngine.Object.FindObjectsByType<ReefFishDetail>(FindObjectsSortMode.None))detail.Select(camera.transform.position,true);ReefCorrectionAudit.Capture(camera,"Renders/FishDetailFix/FullMeshes.png");}
 public static void Validate(){Run();int count=0;long full=0,far=0;foreach(var detail in UnityEngine.Object.FindObjectsByType<ReefFishDetail>(FindObjectsSortMode.None)){count++;full+=detail.full.triangles.Length/3;far+=detail.distant.triangles.Length/3;foreach(var mesh in new[]{detail.medium,detail.distant}){int expected=detail.full.uv2.Count(t=>t.x>.5f),actual=mesh.uv2.Count(t=>t.x>.5f);if(actual!=expected||mesh.normals.Length!=mesh.vertexCount||mesh.uv.Length!=mesh.vertexCount)throw new Exception("Distance fish lost eyes or surface data");}var filter=detail.GetComponent<MeshFilter>();detail.Select(detail.transform.position);if(filter.sharedMesh!=detail.full)throw new Exception("Close fish detail lost");detail.Select(detail.transform.position+Vector3.right*40);if(filter.sharedMesh!=detail.distant)throw new Exception("Distance mesh not selected");detail.Select(detail.transform.position+Vector3.right*40,true);if(filter.sharedMesh!=detail.full)throw new Exception("Held fish did not regain full detail");}if(count!=227||far>full*.65)throw new Exception("Insufficient distance reduction "+count+" "+full+" "+far);Debug.Log("QUEST_FISH_DETAIL_VALIDATED fish="+count+" fullTriangles="+full+" distantTriangles="+far+" eyesUVNormals=preserved closeAndHeld=full sameRendererAndColliders=true");ReefRealismPass.Validate();QuestReefBuild.GrabCheck();FishMotionValidation.Run();}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");typeof(QuestReefBuild).GetMethod("OptimizeScene",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,null);var camera=Camera.main;camera.farClipPlane=60;camera.fieldOfView=90;camera.aspect=1;QualitySettings.lodBias=.65f;var origin=camera.transform.position;
  if(UnityEngine.Object.FindObjectsByType<ReefOptics>(FindObjectsSortMode.None).Length!=0||UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Any(c=>c.depthTextureMode!=DepthTextureMode.None))throw new Exception("Android retained the desktop depth request");Debug.Log("ANDROID_DESKTOP_DEPTH_REMOVED cameras="+UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Length);
  foreach(var detail in UnityEngine.Object.FindObjectsByType<ReefFishDetail>(FindObjectsSortMode.None))detail.Select(camera.transform.position);
  for(int yaw=0;yaw<360;yaw+=45){camera.transform.rotation=Quaternion.Euler(0,yaw,0);var planes=GeometryUtility.CalculateFrustumPlanes(camera);var disabled=new HashSet<Renderer>();foreach(var group in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None)){var levels=group.GetLODs();float distance=Mathf.Max(.01f,Vector3.Distance(camera.transform.position,group.transform.TransformPoint(group.localReferencePoint)));var s=group.transform.lossyScale;float height=group.size*Mathf.Max(Mathf.Abs(s.x),Mathf.Abs(s.y),Mathf.Abs(s.z))*QualitySettings.lodBias/(2*distance*Mathf.Tan(camera.fieldOfView*Mathf.Deg2Rad*.5f));int chosen=Array.FindIndex(levels,l=>height>=l.screenRelativeTransitionHeight);for(int i=0;i<levels.Length;i++)if(i!=chosen)foreach(var renderer in levels[i].renderers)disabled.Add(renderer);}
   var totals=new Dictionary<string,long>();long triangles=0;int calls=0;foreach(var renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None)){if(!renderer.enabled||disabled.Contains(renderer)||!GeometryUtility.TestPlanesAABB(planes,renderer.bounds))continue;var filter=renderer.GetComponent<MeshFilter>();if(!filter||!filter.sharedMesh)continue;long count=0;for(int sub=0;sub<filter.sharedMesh.subMeshCount;sub++)count+=(long)filter.sharedMesh.GetIndexCount(sub)/3;triangles+=count;calls++;string key=renderer.sharedMaterial?renderer.sharedMaterial.shader.name:"No material";if(renderer.name.StartsWith("Scanned"))key+=" scanned";totals.TryGetValue(key,out long old);totals[key]=old+count;}
   Debug.Log("REEF_RENDER_AUDIT yaw="+yaw+" estimatedVisibleTriangles="+triangles+" renderers="+calls+" groups="+string.Join(";",totals.OrderByDescending(p=>p.Value).Take(6).Select(p=>p.Key+":"+p.Value)));
  }
 }
}
}
